// Validate + clean the Claude draft (server-side guarantees; never trust the model blindly).
// ESSENTIALS per task type (Plan v2 D2). To add a task type: add it here, in the schema enum
// of "Task Draft Schema", in workflow 01 TASK_TEMPLATES and in the DB check constraint.
const ESSENTIALS = {
  doctor_appointment:    ['organisation.phone', 'person.name', 'reason_category', 'is_new_patient', 'insurance_type', 'time_windows'],
  authority_appointment: ['organisation.phone', 'person.name', 'goal_user', 'time_windows'],
  landlord_request:      ['organisation.phone', 'person.name', 'fact:address', 'goal_user', 'time_windows'],
  contract_question:     ['organisation.phone', 'person.name', 'fact:contract_type'],
  bank_enquiry:          ['organisation.phone', 'person.name', 'goal_user'],
  pharmacy_question:     ['organisation.phone', 'person.name', 'fact:medicine'],
  restaurant_booking:    ['organisation.phone', 'person.name', 'time_windows', 'constraints.party_size'],
  other_call:            ['organisation.phone', 'person.name', 'goal_user']
};
const TYPES = Object.keys(ESSENTIALS);
const LANGS = ['en','ar','tr','uk','ru','fa','prs','hi','es','fr','pl','vi','zh','de'];
const REASONS = ['first_visit','checkup','acute','follow_up','specialist','other'];
const REFUSE = ['emergency','not_by_phone','unsafe'];
const HEALTH_RE = /(?<!\p{L})(?:(?:schmerz|kopfschmerz|bauchschmerz|fieber|husten|übelkeit|erbrechen|durchfall|ausschlag|schwanger|depressi|angststörung|diabet|krebs|infektion|entzündung|allergi|asthma|blutung|migräne|grippe|symptom|diagnos|headache|nausea|vomit|diarrh|pregnan|depress|anxiety|cancer|infection|inflammation|allerg|bleeding|migraine|fever|cough|painful|ağrı|ateş|öksürük|hamile|біль|боль|кашель)\p{L}*|(?:flu|rash|pain|sick|krank|krankheit)(?!\p{L}))/giu;
const HEALTH_RE_AR = /(ألم|آلام|حمى|سعال|حامل|سرطان|اكتئاب|إسهال|صداع)/gu;
const strip = s => String(s ?? '').replace(HEALTH_RE, '').replace(HEALTH_RE_AR, '').replace(/\s{2,}/g, ' ').replace(/\s+([,.;:!?])/g, '$1').trim();
const hasHealth = s => { HEALTH_RE.lastIndex = 0; HEALTH_RE_AR.lastIndex = 0; return HEALTH_RE.test(String(s ?? '')) || HEALTH_RE_AR.test(String(s ?? '')); };
const str = (v, n) => (v == null ? '' : String(v)).trim().slice(0, n);

const d = $json.output ?? $json;
const input = $('Check Origin + Size').item.json;
const taskType = TYPES.includes(d.task_type) ? d.task_type : 'other_call';
const userLang = LANGS.includes(d.user_language) ? d.user_language : input.ui_lang;
const isPharmacy = taskType === 'pharmacy_question';
let sensitive = d.sensitive_removed === true;

// phone: strip spaces, '/', '-', '(', ')' then validate German format
let phone = str(d.organisation?.phone, 30).replace(/[\s\/\-()]/g, '');
if (phone.startsWith('0049')) phone = '+49' + phone.slice(4);
if (phone && !/^(\+49|0)\d{6,14}$/.test(phone)) phone = '';

let goalUser = str(d.goal_user, 200);
let goalDe = str(d.goal_de, 300);
// goals never carry health details (medicine names are allowed only as a pharmacy fact)
if (hasHealth(goalUser)) { goalUser = strip(goalUser); sensitive = true; }
if (hasHealth(goalDe)) { goalDe = strip(goalDe); sensitive = true; }

const today = $now.setZone('Europe/Berlin').startOf('day');
const windows = (Array.isArray(d.time_windows) ? d.time_windows : [])
  .filter(w => w && /^\d{4}-\d{2}-\d{2}$/.test(w.date) && /^\d{2}:\d{2}$/.test(w.from) && /^\d{2}:\d{2}$/.test(w.to) && w.from < w.to)
  .filter(w => { const dt = DateTime.fromISO(w.date, { zone: 'Europe/Berlin' }); return dt >= today && dt <= today.plus({ days: 60 }); })
  .slice(0, 3)
  .map(w => ({ date: w.date, from: w.from, to: w.to }));

const c = d.constraints || {};
const constraints = {};
if (Number.isFinite(c.budget_max_eur) && c.budget_max_eur > 0) constraints.budget_max_eur = c.budget_max_eur;
if (Number.isInteger(c.party_size) && c.party_size > 0 && c.party_size <= 30) constraints.party_size = c.party_size;
if (str(c.deadline, 40)) constraints.deadline = str(c.deadline, 40);
if (str(c.notes_de, 200) && !hasHealth(c.notes_de)) constraints.notes_de = str(c.notes_de, 200);

const facts = [];
for (const f of (Array.isArray(d.allowed_facts) ? d.allowed_facts : []).slice(0, 8)) {
  const key = str(f?.key, 40).toLowerCase().replace(/[^a-z0-9_]/g, '_');
  const value = str(f?.value, 80);
  if (!key || !value) continue;
  const isMedicine = isPharmacy && /medic|medik|product|produkt/.test(key);
  if (!isMedicine && hasHealth(value)) { sensitive = true; continue; }
  facts.push({ key, label: str(f.label || key, 60), value });
}

const isDoctor = taskType === 'doctor_appointment';
const draft = {
  task_type: taskType,
  user_language: userLang,
  person: { name: str(d.person?.name, 80) },
  organisation: { name: str(d.organisation?.name, 120), phone, category: str(d.organisation?.category, 40) },
  goal_user: goalUser,
  goal_de: goalDe,
  time_windows: windows,
  constraints,
  allowed_facts: facts,
  reason_category: isDoctor && REASONS.includes(d.reason_category) ? d.reason_category : null,
  is_new_patient: isDoctor && typeof d.is_new_patient === 'boolean' ? d.is_new_patient : null,
  has_referral: isDoctor && typeof d.has_referral === 'boolean' ? d.has_referral : null,
  insurance_type: isDoctor && ['gkv','pkv','other'].includes(d.insurance_type) ? d.insurance_type : null,
  insurance_name: isDoctor ? (str(d.insurance_name, 80) || null) : null,
  opening_de: str(d.opening_de, 400),
  opening_user: str(d.opening_user, 400),
  sensitive_removed: sensitive,
  refuse_reason: REFUSE.includes(d.refuse_reason) ? d.refuse_reason : null
};
// Disclosure must be in the opening (Plan v2 F6)
if (!/KI-Assistentin/.test(draft.opening_de)) {
  const n = draft.person.name || 'meiner Auftraggeberin';
  draft.opening_de = 'Guten Tag! Hier ist die KI-Assistentin von ' + n + '. Ich rufe für ' + n + ' an, weil ' + n + ' noch nicht so gut Deutsch spricht.';
}

// missing[]: keep model questions (max 3); add deterministic essentials the model forgot
const present = {
  'organisation.phone': !!phone, 'person.name': !!draft.person.name, 'goal_user': !!goalUser,
  'reason_category': !!draft.reason_category, 'is_new_patient': draft.is_new_patient !== null,
  'insurance_type': !!draft.insurance_type, 'time_windows': windows.length > 0,
  'constraints.party_size': !!constraints.party_size
};
const missingFields = ESSENTIALS[taskType].filter(e => e.startsWith('fact:') ? !facts.some(f => f.key.includes(e.slice(5)) || (e === 'fact:medicine' && /medic|produkt|product/.test(f.key))) : !present[e]);
let missing = (Array.isArray(d.missing) ? d.missing : [])
  .filter(m => m && str(m.question_user, 300))
  .map(m => ({ field: str(m.field, 60), question_user: str(m.question_user, 300), options: Array.isArray(m.options) ? m.options.slice(0, 6).map(o => str(o, 60)).filter(Boolean) : [] }));
missing = missing.slice(0, 3);
const essentials_missing = missingFields;

return { json: { ok: true, draft: { ...draft, missing, essentials_missing, ready: missingFields.length === 0 && !draft.refuse_reason } } };
